use crate::aap::caps::types::{FeedDocument, FetchFailure};
use crate::aap::caps::{http_client, state_rw};

/// The hosts this node's `HTTPClient` handle is scoped to. A request outside
/// this set is a trap at the boundary, so such URLs are reported as failures
/// here instead of being attempted: one bad subscription must not fail the tick.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key in the shared store under which the most recent input is recorded.
const LAST_INPUT_KEY: &str = "last-input";

/// Extract the lowercase host of an http(s) URL, or `None` if it is not one.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let (scheme, rest) = trimmed.split_once("://")?;
    if !(scheme.eq_ignore_ascii_case("http") || scheme.eq_ignore_ascii_case("https")) {
        return None;
    }
    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#' || c == '\\')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    // Drop any userinfo: the host is what follows the last '@'.
    let host_port = match authority.rsplit_once('@') {
        Some((_, hp)) => hp,
        None => authority,
    };
    // Drop a numeric port, if present.
    let host = match host_port.rsplit_once(':') {
        Some((h, p)) if p.chars().all(|c| c.is_ascii_digit()) => h,
        Some(_) => return None,
        None => host_port,
    };
    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(host) => ALLOWED_HOSTS.iter().any(|allowed| *allowed == host),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call, one URL per line.
        state_rw::put(LAST_INPUT_KEY, &subscriptions.urls.join("\n"));

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("not fetched: host is outside this node's allowlist"),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

The world imports `aap:caps/state-rw@0.1.0` as requested, and each call writes the subscription URLs, one per line, under `last-input` before fetching. Until the graph definition grants that interface, a host that provides only `http-client` will refuse to instantiate this component.

